// Generate mock property data
const cities = [
  { name: 'Limassol', nameHe: 'לימסול', coords: [34.707817, 33.022469] },
  { name: 'Paphos', nameHe: 'פאפוס', coords: [34.755291, 32.408562] },
  { name: 'Larnaca', nameHe: 'לרנקה', coords: [34.916641, 33.629456] },
  { name: 'Nicosia', nameHe: 'ניקוסיה', coords: [35.185566, 33.382869] }
];

const propertyTypes = [
  { type: 'villa', typeHe: 'וילה' },
  { type: 'apartment', typeHe: 'דירה' },
  { type: 'penthouse', typeHe: 'פנטהאוז' }
];

const randomCity = cities[Math.floor(Math.random() * cities.length)];
const randomType = propertyTypes[Math.floor(Math.random() * propertyTypes.length)];
const basePrice = Math.floor(Math.random() * 500000) + 150000;

const property = {
  type: 'property',
  content: {
    title: `${randomType.type.charAt(0).toUpperCase() + randomType.type.slice(1)} in ${randomCity.name}`,
    titleHe: `${randomType.typeHe} ב${randomCity.nameHe}`,
    price: basePrice,
    priceILS: basePrice * 3.75,
    location: {
      city: randomCity.name,
      cityHe: randomCity.nameHe,
      area: 'Prime Location',
      areaHe: 'מיקום מרכזי',
      coordinates: randomCity.coords
    },
    features: {
      bedrooms: Math.floor(Math.random() * 3) + 2,
      bathrooms: Math.floor(Math.random() * 2) + 1,
      sqm: Math.floor(Math.random() * 150) + 100,
      pool: Math.random() > 0.5,
      seaview: Math.random() > 0.6,
      parking: true
    },
    description: `Beautiful ${randomType.type} in ${randomCity.name} with modern amenities and excellent investment potential.`,
    descriptionHe: `${randomType.typeHe} מהמם ב${randomCity.nameHe} עם שירותים מודרניים ופוטנציאל השקעה מצוין.`,
    images: [
      'https://images.unsplash.com/photo-1512917774080-9991f1c4c750',
      'https://images.unsplash.com/photo-1600596542815-ffad4c1539a9'
    ],
    roi: {
      rentalYield: (Math.random() * 4 + 4).toFixed(1),
      appreciation: (Math.random() * 5 + 5).toFixed(1)
    },
    propertyType: randomType.type,
    propertyTypeHe: randomType.typeHe,
    slug: `${randomType.type}-${randomCity.name.toLowerCase()}-${Date.now()}`
  }
};

return [{ json: property }];

